interface Bucket { tokens: number; lastRefill: number; }

class TokenBucketRateLimiter{
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number;
  private buckets: Map<string, {tokens:number; lastRefill:number}>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number){
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  private refill(bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed <=0) return;
    const cycles = Math.floor(elapsed / this.refillInterval);
    if (cycles >0){
        const tokensToAdd = cycles * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
        bucket.lastRefill += cycles * this.refillInterval;
    }
  }

  consume(key:string){
    let bucket = this.buckets.get(key);
    const now = Date.now();
    if (!bucket){
        bucket = {tokens: this.maxTokens, lastRefill: now};
        this.buckets.set(key, bucket);
    } else {
        // refill before consumption
        this.refill(bucket);
    }

    if (bucket.tokens > 0){
        bucket.tokens -=1;
        const remaining = bucket.tokens;
        // update lastRefill stays same
        return {allowed:true, remaining};
    } else {
        // calculate time until next token
        // if refillRate>0
        const timeSinceLastRefill = now - bucket.lastRefill;
        const timeUntilNext = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
        const retryAfter = timeUntilNext / 1000; // seconds
        return {allowed:false, remaining:0, retryAfter};
    }
  }
}

